import re, sys
chunk = sys.argv[1].split(',')
root = sys.argv[2]
files = [root + '/explorations/coordinator/FACTS.md', root + '/explorations/coordinator/POSITIONS.md']
for f in files:
    for line in open(f):
        m = re.match(r'- ([FP]-\d+) ', line)
        if not m:
            continue
        src = m.group(1)
        if src in chunk and '--all' not in sys.argv:
            continue
        sents = re.split(r'(?<=[.;])\s+', line)
        for n in chunk:
            if n == src:
                continue
            for s in sents:
                if re.search(re.escape(n) + r'\b', s):
                    print(f'{n} <- {src}: {s.strip()[:450]}')

